#include <iostream>
using namespace std;

long long A[105][105], B[105][105], C[105][105];

int main() {
    int r1, c1, n1;
    if (!(cin >> r1 >> c1 >> n1)) return 0;
    for (int i = 0; i < n1; i++) {
        int r, c, v; cin >> r >> c >> v;
        A[r][c] = v;
    }

    int r2, c2, n2;
    cin >> r2 >> c2 >> n2;
    for (int i = 0; i < n2; i++) {
        int r, c, v; cin >> r >> c >> v;
        B[r][c] = v;
    }

    if (c1 != r2) {
        cout << "ERROR\n";
        return 0;
    }

    bool any = false;
    for (int i = 1; i <= r1; i++)
        for (int j = 1; j <= c2; j++) {
            long long sum = 0;
            for (int k = 1; k <= c1; k++) sum += A[i][k] * B[k][j];
            C[i][j] = sum;
            if (sum != 0) any = true;
        }

    if (!any) {
        cout << "The answer is a Zero Matrix\n";
        return 0;
    }

    for (int i = 1; i <= r1; i++)
        for (int j = 1; j <= c2; j++)
            if (C[i][j] != 0) cout << i << " " << j << " " << C[i][j] << "\n";
    return 0;
}
